from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parents[1]
slides=[
('Follow the agent journey.','A terminal-first technical demonstration.','Git → Flux → KRO → runtime → protected API → skill and MCP → observability.','DICE gives a team a repeatable way to declare an agent and consume its API. The receiving systems provide the execution evidence.'),
('Reviewed intent becomes runtime.','Agent request and platform policies are versioned in Git.','git show "$DEMO_COMMIT:$DEMO_GITOPS_PATH/$DEMO_OWNER_FILE"\nflux get source git "$DEMO_FLUX_SOURCE"\nflux get kustomization "$DEMO_FLUX_KUSTOMIZATION"','Show the approved commit and its applied Flux revision. KRO composes the resources in the installed graph. A slide is not a fresh deployment receipt.'),
('Watch this generation come online.','Follow the owner, generated Agent, workload, route and policy.','kubectl get "$DEMO_OWNER_RESOURCE" "$DEMO_OWNER_NAME"\nkubectl get agent "$DEMO_AGENT_NAME" -w\nkubectl rollout status deployment/"$DEMO_DEPLOYMENT"','Use the fully scoped commands in the command sheet. Accepted and Ready must refer to the current generation. Inspect route acceptance before calling the API.'),
('Consume the protected API.','An application can use the same front door.','ask_agent \'Reply with exactly PONG. Do not call tools.\' PONG','One request. A completed native task. An exact semantic PONG check. This establishes the selected caller and model path.'),
('Read the reviewed skill.','GitLab is the source of versioned guidance.','GitLab revision → approved release → runtime mount\nSKILL.md + approved reference documents','Show the actual publication mechanism and immutable revision. A mounted file is availability evidence; a native skill call establishes use.'),
('Invoke the selected MCP operation.','Guidance and tool permission are separate responsibilities.','ask_agent "$(cat "$DEMO_PROMPT_FILE")"\njq --slurpfile expected "$DEMO_EXPECTED_CALLS" \\\n  -f evidence/tool-calls.jq "$DICE_LAST_RECEIPT"','Inspect the exact native skill/document/MCP calls and returned results. Show separate backend completion evidence and bounded read-back. Label synthetic data.'),
('Inspect the gateway boundary.','Show the actual route, backend and attached policies.','Caller identity → protected agent API\nAgent identity → approved MCP API','Route configuration is not enforcement proof. Compare approved allowed and denied requests using existing permissions. Keep the two identity boundaries separate.'),
('Follow the same request.','Grafana and OTel expose the observed operations.','Native task/context ID → observed trace ID\nTrace → model and tool spans → logs and metrics','Use request correlation, not the latest trace. Show errors, usage provenance and missing fields. A five-minute metric window is not automatically one transaction.'),
('Register ownership and approved connections.','Registry metadata supports governance.','Owner + agent version + skill release + MCP version\nApproved identity, audience and destination permissions\nAcceptance receipts','A proposed registry remains design. Existing Entra objects are administrative evidence. Token exchange and destination authorization need receiving-system proof.'),
('Declare the agent. Consume the API.','Keep the deployment and execution evidence together.','Reviewed commit · owner UID · current generation\nNative task · tool results · backend execution\nObserved traces · tested policy decisions','DICE makes the journey repeatable. Retain the exact resources for questions, then retire through the existing GitOps process when agreed.')]
sections=[]
for i,(title,sub,code,notes) in enumerate(slides,1):
 sections.append(f'<section id="stage-{i}" class="slide" aria-label="Slide {i}"><div class="kicker">UK8S DICE / {i:02d}</div><h1>{escape(title)}</h1><p class="sub">{escape(sub)}</p><pre>{escape(code)}</pre><aside>{escape(notes)}</aside><footer>Explanation and presenter prompts. Verify with receiving-system evidence.<span>{i:02d} / {len(slides):02d}</span></footer></section>')
page='''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>DICE terminal-first lifecycle</title><style>*{box-sizing:border-box}body{margin:0;background:#F4F3EE;color:#1C1C1C;font-family:Arial,Helvetica,sans-serif}.slide{display:none;min-height:100vh;padding:5vh 6vw 9vh}.slide.active{display:block}.kicker{font-size:20px;color:#5A5D5C;letter-spacing:1px;border-bottom:1px solid #CCCABC;padding-bottom:16px}h1{font-size:clamp(40px,5.4vw,86px);font-weight:300;line-height:1.08;max-width:1450px;margin:4vh 0 2vh;padding-left:25px;border-left:5px solid #E60000}.sub{font-size:clamp(22px,2.1vw,34px);color:#5A5D5C;max-width:1350px}pre{background:white;border:1px solid #CCCABC;white-space:pre-wrap;overflow-wrap:anywhere;padding:28px;font:clamp(19px,1.8vw,29px)/1.5 monospace;max-width:1500px;min-height:19vh}aside{display:none;color:#5A5D5C;font-size:22px;max-width:1300px}.notes aside{display:block}footer{display:flex;justify-content:space-between;color:#5A5D5C;font-size:18px;border-top:1px solid #CCCABC;margin-top:4vh;padding-top:14px}nav{position:fixed;bottom:0;left:0;right:0;background:#F4F3EE;border-top:1px solid #CCCABC;padding:10px 6vw;display:flex;gap:10px;align-items:center}button,a{font:16px Arial;color:#1C1C1C;background:white;border:1px solid #CCCABC;padding:10px 14px;text-decoration:none;cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid #E60000}button:disabled{opacity:.4;cursor:default}#status{margin-left:auto;color:#5A5D5C}@media print{@page{size:A3 landscape;margin:10mm}.slide,.slide.active{display:block;min-height:265mm;page-break-after:always;padding:10mm}nav,aside{display:none!important}body{print-color-adjust:exact;-webkit-print-color-adjust:exact}h1{font-size:64px}pre{font-size:27px}footer{font-size:18px}}@media(max-width:700px){.slide{padding:24px 20px 100px}footer{display:block}footer span{float:right}nav{padding:10px;flex-wrap:wrap}#status{font-size:14px}}</style></head><body>'''+''.join(sections)+'''<nav aria-label="Presentation navigation"><a href="index.html">All slides</a><button id="prev">Previous</button><button id="next">Next</button><button id="notes">Presenter notes (N)</button><button id="print">Print slides</button><span id="status" aria-live="polite"></span></nav><script>const pages=[...document.querySelectorAll('.slide')];let index=0;function show(value){index=Math.max(0,Math.min(pages.length-1,value));pages.forEach((page,i)=>page.classList.toggle('active',i===index));document.querySelector('#prev').disabled=index===0;document.querySelector('#next').disabled=index===pages.length-1;document.querySelector('#status').textContent=`${index+1} / ${pages.length}`;history.replaceState(null,'',`#stage-${index+1}`)}document.querySelector('#prev').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);document.querySelector('#notes').onclick=()=>document.body.classList.toggle('notes');document.querySelector('#print').onclick=()=>window.print();document.addEventListener('keydown',event=>{if(['INPUT','TEXTAREA'].includes(event.target.tagName))return;if(event.key==='ArrowRight'||event.key==='PageDown'){event.preventDefault();show(index+1)}if(event.key==='ArrowLeft'||event.key==='PageUp'){event.preventDefault();show(index-1)}if(event.key.toLowerCase()==='n')document.body.classList.toggle('notes')});function readHash(){const requested=Number(location.hash.replace('#stage-',''))-1;show(Number.isFinite(requested)&&requested>=0?requested:0)}window.addEventListener('hashchange',readHash);readHash();</script></body></html>'''
(root/'slides/lifecycle.html').write_text(page)
(root/'slides/README.md').write_text('''# Presentation library\n\nOpen `index.html`. It links the new ten-slide terminal-first lifecycle deck and all top-level HTML presentation pages from the previously published DICE classic bundle. Their local HTML supporting-reference closure is copied into `previous/`, so the primary decks and their on-page source links travel with this folder. The two managed-Kubernetes presentations are included under `platform/`.\n\nThe new deck uses Left/Right or Page Up/Page Down, a notes toggle with N, and landscape printing. The earlier decks retain their existing controls. Simulations, historical receipts and proposed designs retain their original labels. The live frontend page needs its existing backend; the work bundle does not start one.\n\n`SOURCE-MANIFEST.json` records the copied paths, hashes and source commit. The original source is https://github.com/davidmarkgardiner/kagent-work-bundles/tree/main/secure-kro-classic-kagent. No video, voice generation, controller installation or public upload is required to present these HTML slides.\n''')
print('Built',len(slides),'offline lifecycle slides with presenter notes.')
